const ganttEl = id => document.getElementById(id);
const ganttNode = (tag, cls, value) => { const el = document.createElement(tag); if (cls) el.className = cls; if (value != null) el.textContent = value; return el; };

function ganttDay(value) {
  if (!value) return null;
  const iso = value.match(/^(\d{4})-(\d{2})-(\d{2})(?:[ \t]+(?:[01]?\d|2[0-3]):[0-5]\d)?$/);
  const local = value.match(/^(\d{1,2})[./](\d{1,2})[./](\d{4})(?:[ \t]+(?:[01]?\d|2[0-3]):[0-5]\d)?$/);
  const parts = iso ? [+iso[1], +iso[2], +iso[3]] : local ? [+local[3], +local[2], +local[1]] : null;
  if (!parts) return null;
  const day = Date.UTC(parts[0], parts[1]-1, parts[2]);
  const check = new Date(day);
  return check.getUTCFullYear() === parts[0] && check.getUTCMonth()+1 === parts[1] && check.getUTCDate() === parts[2] ? day : null;
}
function ganttFormat(day) {
  return new Date(day).toLocaleDateString(UI === 'ro' ? 'ro-RO' : 'en-US', { timeZone:'UTC', day:'numeric', month:'short', year:'numeric' });
}
function ganttParse(text) {
  const tasks = [], definitions = new Map(), problems = [];
  let fence = null;
  text.split('\n').forEach((line, lineIndex) => {
    const marker = line.match(/^[ \t]*(`{3,}|~{3,})([^\n]*)$/);
    if (fence) {
      if (marker && marker[1][0] === fence.character && marker[1].length >= fence.length && /^[ \t\r]*$/.test(marker[2])) fence = null;
      return;
    }
    if (marker && (marker[1][0] === '~' || !marker[2].includes('`'))) {
      fence = { character: marker[1][0], length: marker[1].length };
      return;
    }
    const match = line.match(GANTT_TASK);
    if (!match) return;
    let body = match[2].replace(/^~(?:inwork|onhold|blocked)(?:[ \t]+|$)/, '');
    const refs = [], deps = [], owners = [], dates = {};
    body = body.replace(GANTT_FLAG, (all, lead, kind, number) => { (kind === '#' ? refs : deps).push(number); return lead; });
    const leadOwner = body.match(GANTT_OWNER_PREFIX);
    if (leadOwner) { owners.push(leadOwner[1].replace(/[ \t]+/g, ' ')); body = body.slice(leadOwner[0].length).trimStart(); }
    body = body.replace(GANTT_OWNER_INLINE, (all, name) => { if (!owners.includes(name)) owners.push(name); return ' '; });
    const importance = (body.match(GANTT_PRIORITY) || [])[2] || '';
    body = body.replace(GANTT_PRIORITY, '$1');
    body = body.replace(GANTT_DATE, (all, lead, kind, value) => { dates[kind.toLowerCase()] = value; return lead; });
    if (window.ScuLaCal) {
      const marks = ScuLaCal.findMarks(body);
      for (const hit of marks) {
        const m = hit.mark, interval = m.endDate !== m.date || !!m.endTime;
        if (interval && dates.start == null) dates.start = m.date + (m.allDay ? '' : ' ' + m.time);
        if (dates.end == null && (interval || m.allDay)) dates.end = m.endDate || m.date;
        if (!interval && !m.allDay && dates.start == null) dates.start = m.date + ' ' + m.time;
      }
      for (let i=marks.length-1; i>=0; i--) body = body.slice(0, marks[i].index) + body.slice(marks[i].index + marks[i].length);
    }
    const plain = [...body.matchAll(/(^|[ \t(])(\d{4}-\d{2}-\d{2}|\d{1,2}[./]\d{1,2}[./]\d{4})(?=$|[ \t),;.!?])/g)];
    if (plain.length > 1 && dates.start == null) dates.start = plain[0][2];
    if (plain.length && dates.end == null) dates.end = plain[plain.length-1][2];
    body = body.replace(/(^|[ \t(])(\d{4}-\d{2}-\d{2}|\d{1,2}[./]\d{1,2}[./]\d{4})(?=$|[ \t),;.!?])/g, '$1');
    const title = body.replace(/\[\[([^\]|]+)(?:\|([^\]]+))?\]\]/g, (_, target, alias) => alias || target)
      .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1').replace(/[*_`]/g, '').replace(/\s+/g, ' ').trim() || line.trim();
// Shared helpers for the ad-hoc Playwright checks in this folder. There is no
// test framework in this repo (see CLAUDE.md "no build step, no framework") -
// these are plain Node scripts, run one at a time: `node tests/flow.js`.
//
// Each script drives editor.html straight off disk via a file:// URL and
// asserts on real pixels (getImageData) and real geometry
// (getBoundingClientRect), not screenshots - see HANDOFF.md § "Testing
// approach" for why.
const path = require('path');
const { chromium } = require('playwright');

// This sandbox pre-installs Chromium outside Playwright's usual cache and
// sets PLAYWRIGHT_SKIP_BROWSER_DOWNLOAD, so `chromium.launch()` needs an
// explicit executablePath here. Elsewhere - a normal dev machine or CI that
// ran `npx playwright install` - leave PW_CHROME_PATH unset and Playwright's
// own managed browser is used instead.
const CHROME = process.env.PW_CHROME_PATH || undefined;
const URL = process.env.EDITOR_URL || 'file://' + path.join(__dirname, '..', 'editor.html');

async function open({ mobile = true, width = 412, height = 915 } = {}) {
  if (process.env.VP) {
    const [w, h] = process.env.VP.split('x').map(Number);
    width = w; height = h;
    if (process.env.VP_MOBILE) mobile = process.env.VP_MOBILE === '1';
  }
  const browser = await chromium.launch(CHROME ? { executablePath: CHROME } : {});
  const ctx = await browser.newContext({
    viewport: { width, height },
    deviceScaleFactor: mobile ? 2 : 1,
    isMobile: mobile,
    hasTouch: mobile
  });
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.goto(URL);
  const cdp = await ctx.newCDPSession(page);
  return { browser, ctx, page, cdp, errors };
}

async function newCanvas(page) {
  await page.click('#newCanvasBtn');
  await page.click('#newCanvasCreate');
  await page.waitForTimeout(120);
}

// --- CDP touch synthesis -------------------------------------------------
async function touch(cdp, type, points) {
  await cdp.send('Input.dispatchTouchEvent', {
    type,
    touchPoints: points.map(p => ({ x: Math.round(p.x), y: Math.round(p.y), id: p.id, radiusX: 6, radiusY: 6, force: 1 }))
  });
}

const sleep = ms => new Promise(r => setTimeout(r, ms));

// Pinch: two fingers start at centre±start/2 and move to centre±end/2, along `axis`
async function pinch(cdp, cx, cy, startGap, endGap, steps = 14, angle = 0) {
  const ux = Math.cos(angle), uy = Math.sin(angle);
  const pts = g => ([
    { id: 1, x: cx - ux * g / 2, y: cy - uy * g / 2 },
    { id: 2, x: cx + ux * g / 2, y: cy + uy * g / 2 }
  ]);
  await touch(cdp, 'touchStart', pts(startGap));
"}
